def solve(n: int) -> int:
    """Return the number of prime numbers strictly less than *n*.
    Implements the Sieve of Eratosthenes in a straightforward way.
    Handles non‑positive *n* by returning 0.
    """
    if n <= 2:
        return 0
    # boolean list where is_prime[i] indicates i is prime (for i < n)
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    import math
    limit = int(math.isqrt(n - 1))
    for p in range(2, limit + 1):
        if is_prime[p]:
            # start marking from p*p
            start = p * p
            step = p
            for multiple in range(start, n, step):
                is_prime[multiple] = False
    return sum(is_prime)

