    """0/1 knapsack: maximum total value with given capacity.
    Returns the maximum value achievable with total weight <= capacity.
    """
    n = len(weights)
    if n == 0 or capacity <= 0:
        return 0
    dp = [0] * (capacity + 1)
    for i in range(n):
