    """Parse a single CSV line according to RFC‑style quoting.
    Returns a list of fields. Empty line yields [''].
    """
    fields = []
    i, n = 0, len(line)
    while i < n:
        if line[i] == '"':
            # quoted field
            i += 1
            field = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i+1] == '"':
                        field.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    field.append(line[i])
                    i += 1
            # consume optional comma
            if i < n and line[i] == ',':
                i += 1
            fields.append(''.join(field))
        else:
            # unquoted field (could be empty)
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])
            if i < n and line[i] == ',':
                i += 1
    # handle empty input specially
    if n == 0:
        return ['']
    # if line ends with a comma, the loop will have added a field before the comma, but not after it
    if line and line[-1] == ',':
        fields.append('')
    return fields
