            b = stack.pop()
            a = stack.pop()
            if t == '+':
                res = a + b
            elif t == '-':
                res = a - b
            elif t == '*':
                res = a * b
            else:  # division truncates toward zero
                # Python division truncates toward negative infinity for //, so use int(a / b)
