def solve(matrix):
    """Return the determinant of a square integer matrix as an integer.
    An empty matrix has determinant 1."""
    m = [row[:] for row in matrix]
    n = len(m)
    if n == 0:
        return 1
    for row in m:
        if len(row) != n:
            raise ValueError('matrix must be square')
    det = 1
    for col in range(n):
        # Find pivot
        piv = None
        for r in range(col, n):
            if m[r][col] != 0:
                piv = r
                break
        if piv is None:
            return 0
        if piv != col:
            m[col], m[piv] = m[piv], m[col]
            det = -det
        det *= m[col][col]
        # Eliminate below using integer row ops: r <- r*pv - pivot*row
        for r in range(col + 1, n):
            if m[r][col]:
                pv = m[col][col]
                factor = m[r][col]
                m[r] = [(x * pv - y * factor) for x, y in zip(m[r], m[col])]
                det //= pv  # compensate for the pv we multiplied the row by
    return det

