def solve(a, b):
    # Ensure a is the shorter string to use less memory
    if len(a) > len(b):
        a, b = b, a
    m, n = len(a), len(b)
    # previous row dp
    prev = list(range(m + 1))  # cost of converting a[:i] to empty string
    for j in range(1, n + 1):
        cur = [j] + [0] * m
        bj = b[j - 1]
        for i in range(1, m + 1):
            if a[i - 1] == bj:
                cost = 0
            else:
                cost = 1
            cur[i] = min(prev[i] + 1,          # deletion
                         cur[i - 1] + 1,      # insertion
                         prev[i - 1] + cost)  # substitution
        prev = cur
    return prev[m]

