from fractions import Fraction


def solve(matrix):
    """Return the determinant of a square integer matrix as an integer.
    An empty matrix has determinant 1. Uses exact rational arithmetic."""
    m = [[Fraction(x) for x in row] for row in matrix]
    n = len(m)
    if n == 0:
        return 1
    for row in m:
        if len(row) != n:
            raise ValueError('matrix must be square')
    det = Fraction(1)
    for col in range(n):
        piv = None
        for r in range(col, n):
            if m[r][col] != 0:
                piv = r
                break
        if piv is None:
            return 0  # singular
        if piv != col:
            m[col], m[piv] = m[piv], m[col]
            det = -det
        det *= m[col][col]
        for r in range(col + 1, n):
            f = m[r][col]
            if f:
                factor = f / m[col][col]
                m[r] = [x - y * factor for x, y in zip(m[r], m[col])]
    return int(det)

