def solve(weights, values, capacity):
    import bisect

    def to_num(x):
        if isinstance(x, bool):
            return int(x)
        if isinstance(x, (int, float)):
            return x
        if isinstance(x, str):
            s = x.strip()
            try:
                return int(s)
            except Exception:
                return float(s)
        return x

    cap = to_num(capacity)
    if cap is None or (isinstance(cap, (int, float)) and cap < 0):
        return 0

    free = 0
    raw = []
    for w, v in zip(weights, values):
        wi = to_num(w)
        vi = to_num(v)
        if wi == 0:
            if vi > 0:
                free += vi
        elif wi > 0:
            raw.append((wi, vi))
    if not raw:
        return free
    items = [(w, v) for w, v in raw if w <= cap]
    if not items:
        return free
    n = len(items)

    def mim(sub_items, cap_limit):
        half = len(sub_items) // 2

        def enum(sub):
            states = [(0, 0)]
            for w, v in sub:
                states = states + [(cw + w, cv + v) for cw, cv in states]
            states.sort()
            pruned = []
            best_v = None
            for cw, cv in states:
                if best_v is None or cv > best_v:
                    pruned.append((cw, cv))
                    best_v = cv
            return pruned

        A = enum(sub_items[:half])
        B = enum(sub_items[half:])
        bw = [w for w, _ in B]
        ans = 0
        for cw, cv in A:
            if cw > cap_limit:
                continue
            idx = bisect.bisect_right(bw, cap_limit - cw) - 1
            if idx >= 0:
                t = cv + B[idx][1]
                if t > ans:
                    ans = t
        return ans

    def bandb(sub_items, cap_limit, node_budget=5000000):
        sub_items = sorted(sub_items, key=lambda iv: iv[1] / iv[0], reverse=True)
        m = len(sub_items)
        pw = [0] * (m + 1)
        pv = [0] * (m + 1)
        for i, (w, v) in enumerate(sub_items):
            pw[i + 1] = pw[i] + w
            pv[i + 1] = pv[i] + v

        def bound(i, rem):
            target = pw[i] + rem
            j = bisect.bisect_right(pw, target) - 1
            if j < i:
                w0, v0 = sub_items[i]
                return (rem / w0) * v0
            val = pv[j] - pv[i]
            rem2 = target - pw[j]
            if j < m and rem2 > 0:
                w0, v0 = sub_items[j]
                val += (rem2 / w0) * v0
            return val

        best_v = [0]
        nodes = [0]

        def dfs(i, rem, cur):
            nodes[0] += 1
            if nodes[0] > node_budget:
                return
            if cur > best_v[0]:
                best_v[0] = cur
            if i >= m or cur + bound(i, rem) <= best_v[0]:
                return
            w, v = sub_items[i]
            if w <= rem:
                dfs(i + 1, rem - w, cur + v)
            if nodes[0] <= node_budget:
