def solve(weights, values, capacity):
    """Return the maximum total value for the 0/1 knapsack problem.
    Handles large capacities efficiently by using a dict‑based DP that stores only
    reachable weight/value pairs (sparse DP). This works for both small capacities
    (as classic DP) and huge capacities with a moderate number of items.
    """
    n = len(weights)
    if n == 0 or capacity <= 0:
        return 0
    # Sum values of zero‑weight items (they can always be taken)
    extra = 0
    items = []
    for w, v in zip(weights, values):
        if w == 0:
            if v > 0:
                extra += v
        else:
            items.append((w, v))
    # Use dict DP: key = weight, value = max value for that weight
    dp = {0: 0}
    for w, v in items:
        # iterate over snapshot of current states to avoid using the same item twice
        new_states = {}
        for cur_w, cur_v in dp.items():
            nw = cur_w + w
            if nw > capacity:
                continue
            nv = cur_v + v
            # keep the best value for this new weight
            if nv > dp.get(nw, -1) and nv > new_states.get(nw, -1):
                new_states[nw] = nv
        # merge new_states into dp
        for k, val in new_states.items():
            if val > dp.get(k, -1):
                dp[k] = val
        # optional pruning: keep only the best value for each weight; also remove
        # dominated states (if a heavier weight has <= value than a lighter one)
        # This keeps dp size manageable.
        sorted_items = sorted(dp.items())
        pruned = {}
        max_val = -1
        for wgt, val in sorted_items:
            if val > max_val:
                max_val = val
                pruned[wgt] = val
        dp = pruned
    # The answer is the maximum value among all reachable weights (including extra)
    best = max(dp.values()) if dp else 0
    return best + extra

