from fractions import Fraction
import random

def solve(matrix):
    n = len(matrix)
    if n == 0:
        return 1
    M = [list(r) for r in matrix]
    sign = 1
    prev = 1
    for k in range(n - 1):
        if M[k][k] == 0:
            for i in range(k + 1, n):
                if M[i][k] != 0:
                    M[k], M[i] = M[i], M[k]
                    sign = -sign
                    break
            else:
                return 0
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                M[i][j] = (M[i][j] * M[k][k] - M[i][k] * M[k][j]) // prev
            M[i][k] = 0
        prev = M[k][k]
    return sign * M[n - 1][n - 1]

def det_fraction(mat):
    n = len(mat)
    A = [[Fraction(x) for x in row] for row in mat]
    det = Fraction(1)
    for k in range(n):
        p = None
        for i in range(k, n):
            if A[i][k] != 0:
                p = i
                break
        if p is None:
            return 0
        if p != k:
            A[k], A[p] = A[p], A[k]
            det = -det
        det *= A[k][k]
        inv = A[k][k]
        for i in range(k + 1, n):
            f = A[i][k] / inv
            for j in range(k, n):
                A[i][j] -= f * A[k][j]
    return det

