def solve(weights, values, capacity):
    # 0/1 knapsack using sparse DP suitable for large capacities.
    n = len(weights)
    if n == 0 or capacity <= 0:
        return 0
    # handle zero-weight items directly
    extra = 0
    items = []
    for w, v in zip(weights, values):
        if w == 0:
            if v > 0:
                extra += v
        else:
            items.append((w, v))
    dp = {0: 0}  # weight -> max value
    for w, v in items:
        new_dp = dp.copy()
        for cur_w, cur_v in dp.items():
            nw = cur_w + w
            if nw > capacity:
                continue
            nv = cur_v + v
            if nv > new_dp.get(nw, -1):
                new_dp[nw] = nv
        # prune dominated states: keep only pairs where value is maximal for that weight
        # Sort by weight and keep increasing values
        sorted_items = sorted(new_dp.items())
        pruned = {}
        max_val = -1
        for wt, val in sorted_items:
            if val > max_val:
                max_val = val
                pruned[wt] = val
        dp = pruned
    best = max(dp.values()) if dp else 0
    return best + extra

